<?php
require __DIR__.'/../config/koneksi.php';require_admin();$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$act=$_POST['action']??'';try{if($act==='save'){$id=(int)($_POST['id']??0);$nama=trim($_POST['nama']??'');$email=trim($_POST['email']??'');$role=$_POST['role']??'kasir';$pw=$_POST['password']??'';if($nama===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||!in_array($role,['admin','kasir'],true))throw new Exception();if($id){if($pw!==''){if(strlen($pw)<10)throw new Exception();$q=$pdo->prepare('UPDATE users SET nama=?,email=?,role=?,password=? WHERE id=?');$q->execute([$nama,$email,$role,password_hash($pw,PASSWORD_DEFAULT),$id]);}else{$q=$pdo->prepare('UPDATE users SET nama=?,email=?,role=? WHERE id=?');$q->execute([$nama,$email,$role,$id]);}}else{if(strlen($pw)<10)throw new Exception();$q=$pdo->prepare('INSERT INTO users(nama,email,role,password) VALUES(?,?,?,?)');$q->execute([$nama,$email,$role,password_hash($pw,PASSWORD_DEFAULT)]);}$msg='Data pengguna berhasil disimpan.';}elseif($act==='delete'){if((int)$_POST['id']===(int)$_SESSION['user']['id'])throw new Exception();$q=$pdo->prepare("DELETE FROM users WHERE id=?");$q->execute([(int)$_POST['id']]);$msg='Pengguna dihapus.';}}catch(Throwable $e){$msg='Gagal menyimpan. Periksa email unik, data wajib, dan password minimal 10 karakter. Akun sendiri tidak dapat dihapus.';}}
$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare('SELECT id,nama,email,role FROM users WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}$users=$pdo->query('SELECT id,nama,email,role,created_at FROM users ORDER BY id DESC')->fetchAll();page_start('Manajemen Pengguna');?>
<?php if($msg): ?><div class="alert alert-info"><?=e($msg)?></div><?php endif; ?><div class="row g-3"><div class="col-xl-4"><div class="panel-card"><h3 class="mb-3"><?= $edit?'Edit':'Tambah' ?> Akun</h3><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><label class="form-label">Nama</label><input class="form-control mb-3" name="nama" required value="<?=e($edit['nama']??'')?>"><label class="form-label">Email</label><input class="form-control mb-3" type="email" name="email" required value="<?=e($edit['email']??'')?>"><label class="form-label">Role</label><select class="form-select mb-3" name="role"><option value="kasir" <?=($edit['role']??'')==='kasir'?'selected':''?>>Kasir</option><option value="admin" <?=($edit['role']??'')==='admin'?'selected':''?>>Admin</option></select><label class="form-label">Password <?= $edit?'(kosongkan jika tidak diubah)':'' ?></label><input class="form-control mb-3" type="password" name="password" <?=$edit?'':'required'?> minlength="10"><button class="btn btn-primary w-100">Simpan Akun</button></form></div></div><div class="col-xl-8"><div class="panel-card"><div class="table-responsive"><table class="table modern-table"><thead><tr><th>Pengguna</th><th>Role</th><th>Dibuat</th><th>Aksi</th></tr></thead><tbody><?php foreach($users as $u): ?><tr><td><strong><?=e($u['nama'])?></strong><small class="d-block muted"><?=e($u['email'])?></small></td><td><span class="stock-badge"><?=e(strtoupper($u['role']))?></span></td><td><?=e($u['created_at'])?></td><td><a class="btn btn-sm btn-outline-primary" href="?edit=<?=$u['id']?>">Edit</a><?php if($u['id']!=$_SESSION['user']['id']): ?> <form class="d-inline" method="post" onsubmit="return confirm('Hapus akun ini?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$u['id']?>"><button class="btn btn-sm btn-outline-danger">Hapus</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div></div></div><?php page_end(); ?>
